class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        seen = {}  # Dictionary to store the last seen index of each character
        start = 0  # Start of the current window
        max_len = 0  # Maximum length of the substring

        for i, char in enumerate(s):
            if char in seen and seen[char] >= start:
                # If the character is seen and its index is within the current window
                start = seen[char] + 1  # Move the start of the window to the next index after the last seen occurrence
            else:
                # Character is not seen or outside the current window
                max_len = max(max_len, i - start + 1)  # Update the maximum length of the current window
            seen[char] = i  # Update the last seen index of the character

        return max_len  # Return the maximum length of the substring without repeating characters
